for _ in range(int(input())):
	n = int(input())
	s = list(input())
	result = [''] * n
	map_s = {'R': 'P', 'P': 'S', 'S': 'R'}
	map_ind = {}
	for i in range(n - 1, -1, -1):
		t = map_s[s[i]]
		if t in map_ind:
			result[i] = result[map_ind[t]]
		else:
			result[i] = s[i]
		map_ind[s[i]] = i
	print(''.join((_ for _ in result)))
